typedef struct { int64_t minor; const char *currency; uint8_t scale; } money_t;

money_t money_add(money_t a, money_t b) {   /* caller owns the range check */
    assert(strcmp(a.currency, b.currency) == 0 && a.scale == b.scale);
    return (money_t){ a.minor + b.minor, a.currency, a.scale };
}
/* 1999 with scale 2 means USD 19.99: render at the edge, never via double */
